return results;

const groups = {};
let globalTotals = {
    FLETE: 0, RAD: 0, EAD: 0, SEGURO: 0, ACUSE: 0, COD: 0, OTROS: 0,
    DESCUENTO: 0, SUBTOTAL: 0, IVA: 0, IVA_RET: 0, TOTAL: 0, "Flete_Alianza": 0
};

const sumFields = [
    'FLETE', 'RAD', 'EAD', 'SEGURO', 'ACUSE', 'COD', 'OTROS', 
    'DESCUENTO', 'SUBTOTAL', 'IVA', 'IVA_RET', 'TOTAL', 'Flete_Alianza'
];

$input.all().forEach(item => {
    const comprobante = item.json['cfdi:Comprobante'];
    if (!comprobante) return;

    const facturas = Array.isArray(comprobante) ? comprobante : [comprobante];

    facturas.forEach(factura => {
        let facturaKey = String(factura.Folio || "S/F").trim();

        if (!groups[facturaKey]) {
            groups[facturaKey] = {
                // 1-31
                GUIA: "", RASTREO: "", FACTURA: facturaKey, FECHA_FACTURA: factura.Fecha || "",
                ARGUMENTO: "", MANIFIESTO: "", DESTINO: "", FECHA_ENVIO: "", FECHA_ENTREGA: "",
                REFERENCIA: "", CTE_ORIGEN: "", NOM_ORIGEN: factura['cfdi:Emisor']?.Nombre || "",
                CTE_DESTINO: "", NOM_DESTINO: factura['cfdi:Receptor']?.Nombre || "",
                ESTADO: "", CODIGO_POSTAL: "", LOCALIDAD: "", COLONIA: "", CALLE: "", NUMERO: "",
                IMPORTE_GUIA: "", MODO_PAGO: factura.MetodoPago || "", TIPO_PAGO: factura.FormaPago || "",
                TIPO_ENTREGA: "", STATUS: "", CANTIDAD: "", PESO: "", VOLUMEN: "", TARIFA: "",
                CONTENIDO: "", DESCRIPCION: "",
                // 32-43 (Valores calculados)
                FLETE: 0, RAD: 0, EAD: 0, SEGURO: 0, ACUSE: 0, COD: 0, OTROS: 0,
                DESCUENTO: 0, SUBTOTAL: 0, IVA: 0, IVA_RET: 0, TOTAL: 0,
                // 44-45
                OBSERVACIONES: "", PERSONA_RECIBE: "",
                // 46-52 (Repetidos y específicos)
                IMPTE_ANTES_DE_DESCTO: 0, "FLETE ": 0, "RAD ": 0, "EAD ": 0, 
                OTROS_SERVICIOS: 0, "SEGURO ": 0, "TOTAL ": 0,
                // 53-54
                ES: "N",
                Flete_Alianza: 0
            };
        }

        let flete = 0, rad = 0, ead = 0, seguro = 0, acuse = 0, cod = 0, otros = 0;
        const conceptosRoot = factura['cfdi:Conceptos']?.['cfdi:Concepto'];
        const conceptos = Array.isArray(conceptosRoot) ? conceptosRoot : [conceptosRoot];

        conceptos.forEach(c => {
            if (!c) return;
            const desc = (c.Descripcion || "").toUpperCase();
            const imp = parseFloat(c.Importe || 0);

            if (desc.includes("FLETE")) flete += imp;
            else if (desc.includes("EAD") || desc.includes("ENTREGA A DOMICILIO")) ead += imp;
            else if (desc.includes("RAD") || desc.includes("RECOLECCION A DOMICILIO")) rad += imp;
            else if (desc.includes("SEGURO")) seguro += imp;
            else if (desc.includes("ACUSE")) acuse += imp;
            else if (desc.includes("COD")) cod += imp;
            else otros += imp;
        });

        const row = groups[facturaKey];
        const subtotal = parseFloat(factura.SubTotal || 0);
        const descuento = parseFloat(factura.Descuento || 0);
        const iva = parseFloat(factura['cfdi:Impuestos']?.TotalImpuestosTrasladados || 0);
        const iva_ret = parseFloat(factura['cfdi:Impuestos']?.TotalImpuestosRetenidos || 0);
        const total = parseFloat(factura.Total || 0);

        row.FLETE += flete;
        row.RAD += rad;
        row.EAD += ead;
        row.SEGURO += seguro;
        row.ACUSE += acuse;
        row.COD += cod;
        row.OTROS += otros;
        row.DESCUENTO += descuento;
        row.SUBTOTAL += subtotal;
        row.IVA += iva;
        row.IVA_RET += iva_ret;
        row.TOTAL += total;

        // Asignación de columnas repetidas (mismo valor)
        row.IMPTE_ANTES_DE_DESCTO = row.SUBTOTAL;
        row["FLETE "] = row.FLETE;
        row["RAD "] = row.RAD;
        row["EAD "] = row.EAD;
        row.OTROS_SERVICIOS = row.OTROS;
        row["SEGURO "] = row.SEGURO;
        row["TOTAL "] = row.TOTAL;

        row.Flete_Alianza += (flete * 0.39);

        // Globales
        globalTotals.FLETE += flete;
        globalTotals.RAD += rad;
        globalTotals.EAD += ead;
        globalTotals.SEGURO += seguro;
        globalTotals.ACUSE += acuse;
        globalTotals.COD += cod;
        globalTotals.OTROS += otros;
        globalTotals.DESCUENTO += descuento;
        globalTotals.SUBTOTAL += subtotal;
        globalTotals.IVA += iva;
        globalTotals.IVA_RET += iva_ret;
        globalTotals.TOTAL += total;
        globalTotals.Flete_Alianza += (flete * 0.39);
    });
});

const result = Object.values(groups).map(g => {
    const finalRow = {};
    Object.keys(g).forEach(key => {
        finalRow[key] = (typeof g[key] === 'number') ? g[key].toFixed(2) : g[key];
    });
    return { json: finalRow };
});

const finalTotalRow = {};
const firstRow = Object.values(groups)[0];
if (firstRow) {
    Object.keys(firstRow).forEach(key => {
        const cleanKey = key.trim();
        if (key === "FACTURA") finalTotalRow[key] = "TOTALES";
        else if (globalTotals.hasOwnProperty(cleanKey)) finalTotalRow[key] = globalTotals[cleanKey].toFixed(2);
        else if (key === "Flete_Alianza") finalTotalRow[key] = globalTotals.Flete_Alianza.toFixed(2);
        else if (key === "ES") finalTotalRow[key] = "N";
        else finalTotalRow[key] = "";
    });
    result.push({ json: finalTotalRow });
}

return result;

const items = $input.all();
if (items.length === 0) return [];

// 1. Extraer los nombres de las columnas (las llaves del JSON)
const columnNames = Object.keys(items[0].json);

// 2. Mapear los datos incluyendo una fila artificial al principio para los títulos
const rows = [columnNames, ...items.map(item => Object.values(item.json))].map((rowValues, rowIndex) => {

  // La fila 0 ahora es siempre el encabezado
  const isHeader = rowIndex === 0;
  // Buscamos si la celda de la factura dice "TOTALES" (está en la posición 0)
  const isTotalRow = rowValues[0] === "TOTALES";

  return {
    values: rowValues.map((val, colIndex) => {
      const strVal = String(val || "").trim();
      const isNegative = strVal.startsWith("-");
      const isNumericColumn = colIndex > 0; // Columnas de dinero

      const cellFormat = {
        textFormat: {
          foregroundColor: isNegative ? { red: 0.8, green: 0, blue: 0 } : { red: 0, green: 0, blue: 0 },
          bold: isHeader || isTotalRow,
          fontSize: isHeader ? 11 : 10
        },
        backgroundColor: isHeader ? { red: 0.7, green: 0.7, blue: 0.7 } : // Gris más oscuro para títulos
                         isTotalRow ? { red: 0.9, green: 0.9, blue: 1.0 } : { red: 1, green: 1, blue: 1 },
        horizontalAlignment: isNumericColumn ? "RIGHT" : "LEFT",
        borders: {
          top: { style: "SOLID" }, bottom: { style: "SOLID" },
          left: { style: "SOLID" }, right: { style: "SOLID" }
        }
      };

      const cellData = {};
      const numericValue = parseFloat(strVal.replace(/[$,]/g, ''));

      // Si es el encabezado, forzamos string. Si es dato numérico, enviamos como número.
      if (!isHeader && isNumericColumn && !isNaN(numericValue)) {
        cellData.userEnteredValue = { numberValue: numericValue };
        cellData.userEnteredFormat = { 
          ...cellFormat, 
          numberFormat: { type: "CURRENCY", pattern: "$#,##0.00" } 
        };
      } else {
        cellData.userEnteredValue = { stringValue: strVal };
        cellData.userEnteredFormat = cellFormat;
      }

      return cellData;
    })
  };
});

return [{ json: { rowData: rows } }];

const groups = {};
// Acumuladores globales para la fila final de TOTALES
let globalTotals = {
    FLETE: 0, RAD: 0, EAD: 0, SEGURO: 0, ACUSE: 0, COD: 0, OTROS: 0,
    DESCUENTO: 0, SUBTOTAL: 0, IVA: 0, IVA_RET: 0, TOTAL: 0, "FLETE ALIANZA": 0
};

const fields = ['FLETE', 'RAD', 'EAD', 'SEGURO', 'ACUSE', 'COD', 'OTROS', 'DESCUENTO', 'SUBTOTAL', 'IVA', 'IVA_RET', 'TOTAL'];

$input.all().forEach(item => {
    const cfdis = item.json['cfdi:Comprobante'];
    if (!cfdis) return;

    const facturas = Array.isArray(cfdis) ? cfdis : [cfdis];

    facturas.forEach(factura => {
        // REGLA: Mantener prefijo original (sin limpieza de LMM)
        const facturaKey = String(factura.Folio || "S/F").trim();

        // Inicializar grupo si no existe para sumar facturas iguales
        if (!groups[facturaKey]) {
            groups[facturaKey] = { FACTURA: facturaKey };
            fields.forEach(f => groups[facturaKey][f] = 0);
            groups[facturaKey]['FLETE ALIANZA'] = 0;
        }

        // Extracción de datos
        const flete = parseFloat(factura.FLETE || 0);
        const ead = parseFloat(factura.EAD || 0);
        const descuento = parseFloat(factura.Descuento || factura.DESCUENTO || 0);

        const data = {
            FLETE: flete,
            RAD: parseFloat(factura.RAD || 0),
            EAD: ead,
            SEGURO: parseFloat(factura.SEGURO || 0),
            ACUSE: parseFloat(factura.ACUSE || 0),
            COD: parseFloat(factura.COD || 0),
            OTROS: parseFloat(factura.OTROS || 0),
            DESCUENTO: descuento,
            SUBTOTAL: parseFloat(factura.SubTotal || 0),
            TOTAL: parseFloat(factura.Total || 0),
            IVA: parseFloat(factura['cfdi:Impuestos']?.TotalImpuestosTrasladados || 0),
            IVA_RET: parseFloat(factura['cfdi:Impuestos']?.TotalImpuestosRetenidos || 0)
        };

        // REGLA FLETE ALIANZA: FLETE + EAD - DESCUENTO
        const fAlianza = flete + ead - descuento;

        // Sumar al grupo (Agrupación)
        fields.forEach(f => groups[facturaKey][f] += data[f]);
        groups[facturaKey]['FLETE ALIANZA'] += fAlianza;

        // Sumar a totales globales
        fields.forEach(f => globalTotals[f] += data[f]);
        globalTotals['FLETE ALIANZA'] += fAlianza;
    });
});

// Construir resultado final con redondeo a 2 decimales
const result = Object.values(groups).map(g => {
    const obj = { json: { FACTURA: g.FACTURA } };
    [...fields, 'FLETE ALIANZA'].forEach(f => obj.json[f] = g[f].toFixed(2));
    return obj;
});

// Agregar fila de TOTALES al final
const finalTotalRow = { json: { FACTURA: "TOTALES" } };
[...fields, 'FLETE ALIANZA'].forEach(f => finalTotalRow.json[f] = globalTotals[f].toFixed(2));
result.push(finalTotalRow);

return result;

