for (const item of items) {
    if (!item.binary || !item.binary.data) continue; 

    const binaryKeys = Object.keys(item.binary);
    if (binaryKeys.length !== 1) continue; 

    const originalDynamicKey = binaryKeys[0]; 
    const originalBinary = item.binary[originalDynamicKey];

    const finalFileName = "Compac.xlsx"; // El nombre que verá la contadora

    // 1. ELIMINAMOS la clave dinámica de entrada.
    delete item.binary[originalDynamicKey]; 

    // 2. Creamos la nueva clave ESTÁTICA ('Compac')
    item.binary.Compac = originalBinary; 

    // 3. SOBRESCRIBIMOS la metadata del nombre de archivo con la extensión
    item.binary.Compac.fileName = finalFileName;
}
