  // Extraer LMMADXXXXXX (limpieza)
  const cleanName = name.split('_')[1].split('.')[0];

  // Verificar duplicados
  if (!seen.has(cleanName)) {
    seen.add(cleanName);
    result.push({
      json: {
        fileName: cleanName
      }
    });
  }
});

return result;

